('indo-beef-rendang','food','indo',0,'Beef Rendang','Beef Rendang','Beef Rendang','Langzaam gegaard rundvlees in een rijk gekruide Indonesische saus. Keuze uit nasi goreng of bami goreng. Geserveerd met atjar en kroepoek.','Slow-cooked beef in a rich Indonesian spiced sauce. Served with atjar and prawn crackers. Choose nasi goreng or bami goreng.','Langsam gegartes Rindfleisch in einer reich gewürzten indonesischen Soße. Wahl zwischen Nasi Goreng und Bami Goreng. Serviert mit Atjar und Krupuk.',2095,9,1,NULL),
('indo-ajam-pedis','food','indo',1,'Ajam Pedis','Ajam Pedis','Ajam Pedis','Kip in een pittige Indonesische saus. Keuze uit nasi goreng of bami goreng. Geserveerd met atjar en kroepoek.','Chicken in a spicy Indonesian sauce. Served with atjar and prawn crackers. Choose nasi goreng or bami goreng.','Hähnchen in einer scharfen indonesischen Soße. Wahl zwischen Nasi Goreng und Bami Goreng. Serviert mit Atjar und Krupuk.',1995,9,1,NULL),
('indo-ajam-cashew','food','indo',2,'Ajam Cashew','Ajam Cashew','Ajam Cashew','Kip met cashewnoten in Indonesische saus. Keuze uit nasi goreng of bami goreng. Geserveerd met atjar en kroepoek.','Chicken with cashew nuts in an Indonesian-style sauce. Served with atjar and prawn crackers. Choose nasi goreng or bami goreng.','Hähnchen mit Cashewkernen in indonesischer Soße. Wahl zwischen Nasi Goreng und Bami Goreng. Serviert mit Atjar und Krupuk.',1995,9,1,NULL),
('indo-ajam-bali-roedjak','food','indo',3,'Ajam Bali Roedjak','Ajam Bali Roedjak','Ajam Bali Roedjak','Kip in een kruidige Balinese saus. Keuze uit nasi goreng of bami goreng. Geserveerd met atjar en kroepoek.','Chicken in a fragrant Balinese-style sauce. Served with atjar and prawn crackers. Choose nasi goreng or bami goreng.','Hähnchen in einer würzigen balinesischen Soße. Wahl zwischen Nasi Goreng und Bami Goreng. Serviert mit Atjar und Krupuk.',1995,9,1,NULL),
('indo-kipsate','food','indo',4,'Kip Saté','Chicken Satay','Hähnchen-Saté','Kipsaté met huisgemaakte satésaus. Keuze uit nasi goreng of bami goreng. Geserveerd met atjar en kroepoek.','Chicken satay with homemade satay sauce. Served with atjar and prawn crackers. Choose nasi goreng or bami goreng.','Hähnchen-Saté mit hausgemachter Satésoße. Wahl zwischen Nasi Goreng und Bami Goreng. Serviert mit Atjar und Krupuk.',1995,9,1,NULL),
('indo-vega-rendang','food','indo',5,'Vegetarische Rendang','Vegetarian Rendang','Vegetarisches Rendang','Vegetarische rendang op Indonesische wijze. Keuze uit nasi goreng of bami goreng. Geserveerd met atjar en kroepoek.','Vegetarian Indonesian-style rendang. Served with atjar and prawn crackers. Choose nasi goreng or bami goreng.','Vegetarisches Rendang nach indonesischer Art. Wahl zwischen Nasi Goreng und Bami Goreng. Serviert mit Atjar und Krupuk.',1695,9,1,NULL),
